CREATE TYPE "StoreType" AS ENUM ('product', 'educational-tourism', 'live-in');
CREATE TABLE "users" ("id" UUID NOT NULL, "full_name" VARCHAR(120) NOT NULL, "email" VARCHAR(254) NOT NULL, "phone" VARCHAR(20) NOT NULL, "password_hash" TEXT NOT NULL, "status" VARCHAR(32) NOT NULL DEFAULT 'active', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "roles" ("id" UUID NOT NULL, "name" VARCHAR(32) NOT NULL, CONSTRAINT "roles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "user_roles" ("user_id" UUID NOT NULL, "role_id" UUID NOT NULL, CONSTRAINT "user_roles_pkey" PRIMARY KEY ("user_id", "role_id"));
CREATE TABLE "sessions" ("id" UUID NOT NULL, "token_hash" CHAR(64) NOT NULL, "user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expires_at" TIMESTAMPTZ(3) NOT NULL, "revoked_at" TIMESTAMPTZ(3), CONSTRAINT "sessions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stores" ("id" UUID NOT NULL, "merchant_user_id" UUID NOT NULL, "name" VARCHAR(160) NOT NULL, "type" "StoreType" NOT NULL, "description" TEXT NOT NULL, "status" VARCHAR(32) NOT NULL DEFAULT 'active', "location_label" VARCHAR(160), "address" VARCHAR(500), "latitude" DECIMAL(9,6), "longitude" DECIMAL(9,6), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "stores_pkey" PRIMARY KEY ("id"), CONSTRAINT "stores_coordinate_pair_check" CHECK (("latitude" IS NULL AND "longitude" IS NULL) OR ("latitude" IS NOT NULL AND "longitude" IS NOT NULL)), CONSTRAINT "stores_latitude_range_check" CHECK ("latitude" IS NULL OR "latitude" BETWEEN -90 AND 90), CONSTRAINT "stores_longitude_range_check" CHECK ("longitude" IS NULL OR "longitude" BETWEEN -180 AND 180));
CREATE TABLE "platform_settings" ("id" VARCHAR(32) NOT NULL DEFAULT 'active', "delivery_rate_per_km" DECIMAL(12,2) NOT NULL, "delivery_order_cutoff_time" VARCHAR(5) NOT NULL, "delivery_dispatch_time" VARCHAR(5) NOT NULL, "max_daily_deliveries" INTEGER NOT NULL, "tourism_approval_timeout_hours" INTEGER NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "platform_settings_pkey" PRIMARY KEY ("id"), CONSTRAINT "platform_settings_singleton_check" CHECK ("id" = 'active'));
CREATE TABLE "audit_records" ("id" UUID NOT NULL, "entity_type" VARCHAR(80) NOT NULL, "entity_id" VARCHAR(160) NOT NULL, "actor_id" UUID, "actor_role" VARCHAR(32), "activity_type" VARCHAR(80) NOT NULL, "previous_status" VARCHAR(80), "next_status" VARCHAR(80), "description" TEXT NOT NULL, "reason" TEXT, "is_system" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "audit_records_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE UNIQUE INDEX "roles_name_key" ON "roles"("name");
CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions"("token_hash");
CREATE INDEX "sessions_user_id_idx" ON "sessions"("user_id");
CREATE INDEX "sessions_expires_at_idx" ON "sessions"("expires_at");
CREATE INDEX "stores_merchant_user_id_idx" ON "stores"("merchant_user_id");
CREATE INDEX "stores_type_idx" ON "stores"("type");
CREATE INDEX "audit_records_entity_type_entity_id_idx" ON "audit_records"("entity_type", "entity_id");
CREATE INDEX "audit_records_created_at_idx" ON "audit_records"("created_at");
ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "stores" ADD CONSTRAINT "stores_merchant_user_id_fkey" FOREIGN KEY ("merchant_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "audit_records" ADD CONSTRAINT "audit_records_actor_id_fkey" FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
